mapper.select:
select sttSce.sceneId, concat_ws('',sttSce.SCENE_ID ,'-',e.indId id), e.indId, e.indName, e.remark from stt_scene sttSce left join ( select a.MODEL_ID modelId, a.ind_Id indId, b.ind_name indName, b.remark from stt_stress_indicator a left JOIN stt_indicator b on a.ind_id=b.ind_id
and b.ind_ype=#{indType, jdbcType=VARCHAR}
and a.STT_BUSI_TYPE=#{sttBusiType, jdbcType=VARCHAR}
)e on sttSce.SCENE_TPML_ID = e.modelId
and where sttSce.SCENE_ID=#{sceneId, jdbcType=VARCHAR}
